+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+
+/**
+ * The criteria {@link CustomerRepository} narrows its result set with.
+ *
+ * <p>A filter is the pair of what the user typed and which statuses they picked.
+ * It is passed into the repository so that both the page query and the count
+ * query see the same criteria: the UI stays lazily loaded, and the count it
+ * displays is the backend's own.
+ *
+ * @param name     free text; split on whitespace into terms, every one of which
+ *                 must occur in the first or last name. Blank matches everything
+ * @param statuses the acceptable statuses; empty matches every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Collections.emptySet()
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /** Returns {@code true} when this filter narrows nothing down. */
+    public boolean isEmpty() {
+        return name.isBlank() && statuses.isEmpty();
+    }
+
+    /**
+     * The name terms, normalized for comparison: the name split on whitespace,
+     * with case and accents removed. Empty when the name filter is blank.
+     */
+    public List<String> nameTerms() {
+        if (name.isBlank()) {
+            return List.of();
+        }
+        return Arrays.stream(name.strip().split("\\s+"))
+                .map(CustomerFilter::normalize)
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    /**
+     * Compiles this filter into a predicate. The terms are normalized once, not
+     * once per customer, so the repository can run it over a whole table.
+     */
+    public Predicate<Customer> asPredicate() {
+        if (isEmpty()) {
+            return customer -> true;
+        }
+        List<String> terms = nameTerms();
+        Set<CustomerStatus> allowed = statuses;
+        return customer -> matchesStatus(customer, allowed) && matchesName(customer, terms);
+    }
+
+    private static boolean matchesStatus(Customer customer, Set<CustomerStatus> allowed) {
+        return allowed.isEmpty() || allowed.contains(customer.status());
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        for (String term : terms) {
+            if (!firstName.contains(term) && !lastName.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /**
+     * Folds a string down to what matching compares: lower case, with accents
+     * stripped, so that {@code makinen}, {@code MAKINEN} and {@code mäkinen} all
+     * become the same thing.
+     */
+    public static String normalize(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return decomposed.replaceAll("\\p{M}+", "").toLowerCase(Locale.ROOT);
+    }
+}
