+
+import com.example.customers.domain.Customer;
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerRepository;
+import com.example.customers.domain.CustomerSort;
+import com.example.customers.domain.CustomerStatus;
+import com.example.customers.domain.QueryLog;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+
+/**
+ * The backend side of filtering: what matches, and what it costs.
+ *
+ * <p>No Vaadin and no Spring here — just the repository, the way a database
+ * would be exercised.
+ */
+class CustomerFilteringTest {
+
+    private QueryLog queryLog;
+    private CustomerRepository repository;
+
+    @BeforeEach
+    void setUp() {
+        queryLog = new QueryLog();
+        repository = new CustomerRepository(queryLog);
+    }
+
+    @Test
+    void anEmptyFilterMatchesEverything() {
+        assertEquals(500, repository.count(CustomerFilter.EMPTY));
+        assertEquals(500, repository.count(new CustomerFilter("   ", Set.of())));
+        assertEquals(500, repository.count(null));
+        assertEquals(500, repository.count());
+    }
+
+    @Test
+    void everyNameTermMustMatchTheFirstOrLastName() {
+        assertEquals(2, repository.count(name("ada aal")));
+        assertEquals(2, repository.count(name("aal ada")));
+        assertEquals(2, repository.count(name(" \t aal   ada \n ")));
+        assertEquals(0, repository.count(name("ada virtanen")));
+    }
+
+    @Test
+    void matchingIgnoresCaseAndAccentsBothWays() {
+        assertEquals(15, repository.count(name("makinen")));
+        assertEquals(15, repository.count(name("MAKINEN")));
+        assertEquals(15, repository.count(name("mäkinen")));
+        assertEquals(12, repository.count(name("josephine")));
+        assertEquals(12, repository.count(name("JOSÉPHINE")));
+
+        CustomerFilter filter = name("makinen");
+        assertTrue(repository.findAll(0, 200, List.of(), filter).stream()
+                .allMatch(customer -> customer.lastName().equals("Mäkinen")));
+    }
+
+    @Test
+    void statusesAreOrred() {
+        assertEquals(167, repository.count(status(CustomerStatus.ACTIVE)));
+        assertEquals(333, repository.count(status(CustomerStatus.ACTIVE, CustomerStatus.CLOSED)));
+        assertEquals(500, repository.count(
+                status(CustomerStatus.ACTIVE, CustomerStatus.PENDING, CustomerStatus.CLOSED)));
+    }
+
+    @Test
+    void bothCriteriaMustHold() {
+        CustomerFilter filter = new CustomerFilter("vir", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
+
+        assertEquals(10, repository.count(filter));
+        assertTrue(repository.findAll(0, 10, List.of(), filter).stream()
+                .allMatch(customer -> customer.lastName().equals("Virtanen")
+                        && customer.status() != CustomerStatus.PENDING));
+    }
+
+    @Test
+    void filteredPagingIsPagedAndSorted() {
+        CustomerFilter filter = name("a");
+        int matching = repository.count(filter);
+        assertTrue(matching > CustomerRepository.MAX_PAGE_SIZE,
+                "this test needs a result set larger than one page, was " + matching);
+
+        List<CustomerSort> byLastName = List.of(new CustomerSort("lastName", true));
+        List<Customer> firstPage = repository.findAll(0, 100, byLastName, filter);
+        List<Customer> secondPage = repository.findAll(100, 100, byLastName, filter);
+
+        assertEquals(100, firstPage.size());
+        assertEquals(100, secondPage.size());
+        assertTrue(firstPage.getLast().lastName().compareToIgnoreCase(
+                        secondPage.getFirst().lastName()) <= 0,
+                "the pages must be consecutive in sort order");
+        assertTrue(firstPage.stream().noneMatch(secondPage::contains), "the pages must not overlap");
+    }
+
+    @Test
+    void theBackendStillRefusesOversizedPages() {
+        assertThrows(IllegalArgumentException.class,
+                () -> repository.findAll(0, CustomerRepository.MAX_PAGE_SIZE + 1, List.of(), name("a")));
+    }
+
+    @Test
+    void everyQueryIsStillRecorded() {
+        repository.findAll(0, 50, List.of(), name("aal"));
+        repository.count(name("aal"));
+        repository.findAll(50, 50, List.of(), CustomerFilter.EMPTY);
+        repository.count();
+
+        assertEquals(List.of(15, 500), queryLog.countQueries());
+        assertEquals(2, queryLog.pageQueries().size());
+        assertEquals(new QueryLog.PageQuery(0, 50, 15), queryLog.pageQueries().get(0));
+        assertEquals(new QueryLog.PageQuery(50, 50, 50), queryLog.pageQueries().get(1));
+        assertEquals(65, queryLog.rowsFetched());
+    }
+
+    @Test
+    void filterEqualityIgnoresStatusOrder() {
+        assertEquals(new CustomerFilter("a", Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE)),
+                new CustomerFilter("a", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED)));
+        assertTrue(CustomerFilter.EMPTY.isEmpty());
+        assertTrue(new CustomerFilter(null, null).isEmpty());
+        assertFalse(name("a").isEmpty());
+        assertEquals(List.of("ACTIVE", "CLOSED"),
+                new CustomerFilter("", Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE))
+                        .statuses().stream().map(CustomerStatus::name).toList());
+    }
+
+    private static CustomerFilter name(String text) {
+        return new CustomerFilter(text, Set.of());
+    }
+
+    private static CustomerFilter status(CustomerStatus... statuses) {
+        return new CustomerFilter("", Set.of(statuses));
+    }
+}
