+    // --- helpers -----------------------------------------------------------
+
+    private void open(String path) {
+        page.navigate("http://localhost:" + port + path);
+        waitForVaadin();
+        summary().waitFor();
+    }
+
+    private void waitForVaadin() {
+        page.waitForFunction(AbstractBasePlaywrightIT.WAIT_FOR_VAADIN_SCRIPT);
+    }
+
+    private Locator summary() {
+        return page.getByText(SUMMARY);
+    }
+
+    private Locator nameInput() {
+        return page.locator("vaadin-text-field input");
+    }
+
+    private Locator gridCells() {
+        return page.locator("vaadin-grid-cell-content");
+    }
+
+    /** Types one character at a time, the way a user does. */
+    private void type(String text) {
+        nameInput().click();
+        nameInput().pressSequentially(text);
+    }
+
+    private void clearName() {
+        nameInput().fill("");
+        nameInput().press("Tab");
+    }
+
+    private void selectStatuses(String... statuses) {
+        Locator combo = page.locator("vaadin-multi-select-combo-box");
+        combo.click();
+        for (String status : statuses) {
+            page.getByRole(AriaRole.OPTION).filter(new Locator.FilterOptions().setHasText(status))
+                    .first().click();
+        }
+        combo.press("Escape");
+    }
+
+    /** Clicking a selected status in the dropdown unselects it again. */
+    private void unselectStatuses(String... statuses) {
+        selectStatuses(statuses);
+    }
+
+    /** What the status field shows as selected, read off the component itself. */
+    private String selectedStatuses() {
+        return (String) page.locator("vaadin-multi-select-combo-box")
+                .evaluate("el => el.selectedItems.map(item => item.label).join(',')");
+    }
+
+    private int historyLength() {
+        waitForVaadin();
+        return ((Number) page.evaluate("() => window.history.length")).intValue();
+    }
+
+    /**
+     * Waits for the address bar to carry {@code expected}, then asserts it. The
+     * history update rides along with the round trip, so it lands a moment after
+     * the grid does.
+     */
+    private void assertQuery(String expected) {
+        try {
+            page.waitForURL(url -> expected.equals(queryOf(url)));
+        } catch (RuntimeException e) {
+            // Fall through to the assertion, which reports what it actually says.
+        }
+        assertEquals(expected, query());
+    }
+
+    /** The query string as the address bar shows it, percent-decoding aside. */
+    private String query() {
+        waitForVaadin();
+        return queryOf(page.url());
+    }
+
+    private static String queryOf(String url) {
+        int question = url.indexOf('?');
+        String query = (question < 0) ? "" : url.substring(question);
+        return URLDecoder.decode(query, StandardCharsets.UTF_8);
+    }
+}
